import Foundation

/// Verify the exact URL generated by the UI test after the main app relaunch,
/// then acknowledge only this fixture through the production locked store.
@main
struct VerifyInbox {
  static func main() throws {
    guard CommandLine.arguments.count == 3 else {
      throw SharedTextStore.Failure("Usage: verify-inbox <group-directory> <test-log>")
    }
    let group = URL(fileURLWithPath: CommandLine.arguments[1])
    let log = try String(contentsOfFile: CommandLine.arguments[2], encoding: .utf8)
    let pattern = #"(?m)^SHARE_FIXTURE_URL=(http://127\.0\.0\.1:8765/#gemsnote-ui-[0-9a-f-]{36})$"#
    let expression = try NSRegularExpression(pattern: pattern)
    guard let match = expression.firstMatch(in: log, range: NSRange(log.startIndex..., in: log)),
      let range = Range(match.range(at: 1), in: log) else {
      throw SharedTextStore.Failure("Missing exact test URL")
    }
    let expected = String(log[range])
    let directory = group.appendingPathComponent("SharedTextInbox")
    let queue = directory.appendingPathComponent("queue.json")
    let records = try JSONDecoder().decode([SharedTextRecord].self, from: Data(contentsOf: queue))
    let matches = records.filter { $0.text == expected }
    guard matches.count == 1, let record = matches.first,
      record.accountKey.isEmpty, record.resourceKind == nil else {
      throw SharedTextStore.Failure("Expected exactly one unclaimed URL in the real App Group inbox")
    }
    try record.validate()
    try SharedTextStore(directory: directory).acknowledge(id: record.id)
    print("PASS Safari share persisted across main-app relaunch; removed only fixture \(record.id)")
  }
}
